-- Migración de datos iniciales de inventarios LEM y LEPA

-- 1. Ubicaciones físicas
ON CONFLICT (laboratorio_id, nombre) DO UPDATE SET activo = true;

-- Lote 1 / 8: Catalogo
ON CONFLICT (codigo_unico) DO UPDATE SET nombre = EXCLUDED.nombre, formula_quimica = EXCLUDED.formula_quimica;

-- Lote 1 / 8: Stock
ON CONFLICT (reactivo_id, laboratorio_id) DO UPDATE SET cantidad_actual = EXCLUDED.cantidad_actual, unidad_medida = EXCLUDED.unidad_medida, ubicacion_fisica = EXCLUDED.ubicacion_fisica, estado_fisico = EXCLUDED.estado_fisico;

